**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <cmath>
#include <iomanip>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    int x1, y1, x2, y2;
    plik >> x1 >> y1 >> x2 >> y2;
    int n;
    plik >> n;
    // Prosta Ax+By+C=0
    int A = y2 - y1;
    int B = -(x2 - x1);
    int C = (x2 - x1) * y1 - (y2 - y1) * x1;
    double mian = sqrt((double)(A * A + B * B));
    cout << "Prosta przez (" << x1 << "," << y1 << ") i (" << x2 << "," << y2 << ")" << endl;
    cout << fixed << setprecision(2);
    double suma = 0;
    for (int i = 0; i < n; i++) {
        int px, py;
        plik >> px >> py;
        double dist = abs(A * px + B * py + C) / mian;
        cout << "(" << px << "," << py << "): odleglosc = " << dist << endl;
        suma += dist;
    }
    cout << "Srednia odleglosc: " << suma / n << endl;
    return 0;
}
```

**Wyjasnienie**: Prosta przez (0,0) i (8,6): A=6, B=-8, C=8*0-6*0=0. Rownanie: 6x-8y=0. Mianownik = sqrt(36+64) = sqrt(100) = 10.

Weryfikacja:
- (4,3): |6*4-8*3|/10 = |24-24|/10 = 0/10 = 0.00 (lezy na prostej)
- (2,6): |6*2-8*6|/10 = |12-48|/10 = 36/10 = 3.60
- (8,3): |6*8-8*3|/10 = |48-24|/10 = 24/10 = 2.40
- (6,8): |6*6-8*8|/10 = |36-64|/10 = 28/10 = 2.80
- (10,6): |6*10-8*6|/10 = |60-48|/10 = 12/10 = 1.20
- Srednia: (0+3.60+2.40+2.80+1.20)/5 = 10.00/5 = 2.00
